#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdatomic.h>
#include <pthread.h>
#include <stdbool.h>
#include <unistd.h>

#define NUM_THREADS 16
#define TOTAL_OBJECTS 300000
#define HP_SLOTS_PER_THREAD 2
#define RETIRE_THRESHOLD 100
#define MAX_RETIRED (RETIRE_THRESHOLD + 100)

typedef struct {
    _Atomic(void*) hazard_pointers[NUM_THREADS][HP_SLOTS_PER_THREAD];
} hp_engine_t;

hp_engine_t engine;

__thread struct {
    void* ptrs[MAX_RETIRED];
    int count;
} retired_list;

void hp_acquire(int thread_id, int slot, void *ptr) {
    atomic_store_explicit(&engine.hazard_pointers[thread_id][slot], ptr, memory_order_seq_cst);
}

void hp_release(int thread_id, int slot) {
    atomic_store_explicit(&engine.hazard_pointers[thread_id][slot], NULL, memory_order_seq_cst);
}

void hp_scan(int thread_id) {
    void* active_hps[NUM_THREADS * HP_SLOTS_PER_THREAD];
    int num_active = 0;
    for (int t = 0; t < NUM_THREADS; t++) {
        for (int s = 0; s < HP_SLOTS_PER_THREAD; s++) {
            void* hp = atomic_load_explicit(&engine.hazard_pointers[t][s], memory_order_seq_cst);
            if (hp) active_hps[num_active++] = hp;
        }
    }
    int new_count = 0;
    for (int i = 0; i < retired_list.count; i++) {
        void* rptr = retired_list.ptrs[i];
        bool hazardous = false;
        for (int j = 0; j < num_active; j++) {
            if (active_hps[j] == rptr) {
                hazardous = true;
                break;
            }
        }
        if (!hazardous) {
            free(rptr);
        } else {
            if (new_count < MAX_RETIRED) retired_list.ptrs[new_count++] = rptr;
        }
    }
    retired_list.count = new_count;
}

void hp_retire(int thread_id, void *ptr) {
    if (!ptr) return;
    if (retired_list.count >= MAX_RETIRED) hp_scan(thread_id);
    while (retired_list.count >= MAX_RETIRED) {
        usleep(10);
        hp_scan(thread_id);
    }
    retired_list.ptrs[retired_list.count++] = ptr;
    if (retired_list.count >= RETIRE_THRESHOLD) hp_scan(thread_id);
}

void hp_reclaim_all(int thread_id) {
    while (retired_list.count > 0) {
        hp_scan(thread_id);
        if (retired_list.count > 0) usleep(100);
    }
}

_Atomic(void*) shared_obj;

void* thread_func(void* arg) {
    int thread_id = (int)(intptr_t)arg;
    int objects_per_thread = TOTAL_OBJECTS / NUM_THREADS;
    for (int i = 0; i < objects_per_thread; i++) {
        int* new_obj = malloc(sizeof(int));
        if (!new_obj) continue;
        *new_obj = thread_id;
        void* old_obj = atomic_exchange_explicit(&shared_obj, new_obj, memory_order_seq_cst);
        void* read_obj;
        do {
            read_obj = atomic_load_explicit(&shared_obj, memory_order_seq_cst);
            if (!read_obj) break;
            hp_acquire(thread_id, 0, read_obj);
            if (atomic_load_explicit(&shared_obj, memory_order_seq_cst) != read_obj) {
                hp_release(thread_id, 0);
                continue;
            }
            break;
        } while (1);
        if (read_obj) {
            volatile int val = *(int*)read_obj;
            (void)val;
        }
        hp_release(thread_id, 0);
        if (old_obj != NULL) hp_retire(thread_id, old_obj);
    }
    hp_reclaim_all(thread_id);
    return NULL;
}

int main() {
    for (int t = 0; t < NUM_THREADS; t++) {
        for (int s = 0; s < HP_SLOTS_PER_THREAD; s++) {
            atomic_init(&engine.hazard_pointers[t][s], NULL);
        }
    }
    atomic_init(&shared_obj, NULL);
    pthread_t threads[NUM_THREADS];
    for (int t = 0; t < NUM_THREADS; t++) {
        pthread_create(&threads[t], NULL, thread_func, (void*)(intptr_t)t);
    }
    for (int t = 0; t < NUM_THREADS; t++) {
        pthread_join(threads[t], NULL);
    }
    void *last = atomic_load_explicit(&shared_obj, memory_order_seq_cst);
    if (last) free(last);
    printf("FLAG: Hazard Engine ASAN Success!\n");
    return 0;
}
EOF

